            const merge = mergeGeneratedReports(generated, { selectIncoming: true, openIncoming: "last" }); renderReportList(); renderSelectedReport(); updateStats({ ...(data.summary || {}), students_in_class: state.students.length, generated: state.reports.length, subjects: countSubjects(state.reports), class_average: data.summary?.class_average ?? averageOfReports(state.reports) }); setStatus("Selected Reports Generated", `${generated.length} selected report(s) generated • ${merge.total} report(s) now in the list.`, "ready"); setPreviewStatus("Ready", "ready"); notify(`${generated.length} selected report(s) generated. ${merge.added} added to the list${merge.updated ? ` • ${merge.updated} refreshed` : ""}.`, "generated", "Selected Reports Ready"); transcriptArchiveNotice(generated,data.saved_snapshots); revealGeneratedPreview("Selected reports are ready in the live preview grid."); if (canonicalTerm(c.term) === "THIRD") await compileCumulativeResults({ silent:true, source:"auto" });
