    // ============================================================
    // REMARKS / TRAITS EDITOR
    // ============================================================

    const traitEls = { punctuality: els.traitPunctuality, attendance: els.traitAttendance, reliability: els.traitReliability, neatness: els.traitNeatness, politeness: els.traitPoliteness, honesty: els.traitHonesty, relationship: els.traitRelationship, self_control: els.traitSelfControl, attentiveness: els.traitAttentiveness, perseverance: els.traitPerseverance };
    const psychomotorEls = { handwriting: els.psyHandwriting, games: els.psyGames, sport: els.psySport, drawing: els.psyDrawing, crafts: els.psyCrafts, musical_skills: els.psyMusic };

    function openRemarksForAdmission(admission) { const key = normalizeAdmission(admission), index = state.filteredReports.findIndex(report => normalizeAdmission(reportAdmission(report)) === key); if (index < 0) { notify("Generate or preview this student's report before editing official remarks.", "warning", "Report Required"); return; } state.selectedIndex = index; renderReportList(); renderSelectedReport(); openRemarksEditor("student"); }
    function openRemarksEditor(scope = "student") { const report = getCurrentReport(); if (!report && scope === "student") { notify("Generate or preview a report first.", "warning", "No Report Selected"); return; } populateRemarksStudents(); if (els.remarksScope) els.remarksScope.value = scope; if (report) fillRemarksEditor(report); else { if (els.remarksSummary) els.remarksSummary.innerHTML = `<strong>Class-wide details</strong><span>${esc(armLabel(currentContext().class_arm))}</span><small>Apply common remarks, ratings or next-term details in one action.</small>`; if (els.remarksTeacherName) els.remarksTeacherName.value = clean(els.formTeacher?.value); if (els.remarksNextTerm) els.remarksNextTerm.value = clean(els.nextTerm?.value); } openModal("remarksTraitsModal"); notify(scope === "student" && report ? `Editing official remarks and ratings for ${reportName(report)}.` : "Class-wide remarks and ratings editor opened.", "info", "Report Editor Opened", 2200); }
    function openBulkRemarksEditor() { if (!validateContext() || !state.students.length) { notify("Load a class before applying bulk remarks or ratings.", "warning", "Load Class First"); return; } openRemarksEditor("all"); }
    function populateRemarksStudents() { if (!els.remarksSelect) return; const rows = state.filteredReports.length ? state.filteredReports.map(report => ({ admission_number: reportAdmission(report), full_name: reportName(report) })) : state.students; els.remarksSelect.innerHTML = `<option value="">Select student</option>${rows.map(item => `<option value="${esc(item.admission_number)}">${esc(item.full_name)} — ${esc(item.admission_number)}</option>`).join("")}`; const report = getCurrentReport(); if (report) els.remarksSelect.value = reportAdmission(report); }
    function setRatingInputs(map, nodes) { Object.entries(nodes).forEach(([key, node]) => { if (node) node.value = map?.[key] ?? ""; }); }
    function readRatingInputs(nodes) { const output = {}; Object.entries(nodes).forEach(([key, node]) => { const raw = clean(node?.value); if (!raw) output[key] = ""; else output[key] = Math.max(1, Math.min(6, Math.round(numberValue(raw, 0)))); }); return output; }

