    function initGoldTooltips() {
        const tooltip = premiumNode("reportGoldTooltip"); if (!tooltip) return;
        Object.entries(premiumTips).forEach(([id,tip]) => { const node = premiumNode(id); if (node) node.dataset.reportTip = node.dataset.reportTip || tip; });
        root.querySelectorAll("[title]").forEach(node => { if (!node.dataset.reportTip && node.getAttribute("title")) node.dataset.reportTip = node.getAttribute("title"); if (node.dataset.reportTip) node.removeAttribute("title"); });
        const hide = () => { premiumUi.tooltipTarget = null; tooltip.classList.remove("show"); tooltip.setAttribute("aria-hidden","true"); };
        const show = target => { const tip = target?.dataset?.reportTip; if (!tip || target.disabled) return hide(); premiumUi.tooltipTarget = target; tooltip.textContent = tip; tooltip.setAttribute("aria-hidden","false"); tooltip.classList.add("show"); requestAnimationFrame(() => { const r = target.getBoundingClientRect(), tr = tooltip.getBoundingClientRect(), pad = 10; let left = r.left + r.width/2 - tr.width/2, top = r.top - tr.height - 10; left = Math.max(pad,Math.min(left,window.innerWidth-tr.width-pad)); if (top < pad) top = r.bottom + 10; tooltip.style.left = `${left}px`; tooltip.style.top = `${top}px`; tooltip.style.setProperty("--tip-arrow-left",`${Math.max(12,Math.min(tr.width-18,r.left+r.width/2-left))}px`); }); };
        document.addEventListener("pointerover", event => { const target = event.target.closest?.("[data-report-tip]"); if (target && premiumUi.tooltipTarget !== target) show(target); }); document.addEventListener("pointerout", event => { if (event.target.closest?.("[data-report-tip]") && !event.relatedTarget?.closest?.("[data-report-tip]")) hide(); });
        document.addEventListener("focusin", event => { const target = event.target.closest?.("[data-report-tip]"); if (target) show(target); }); document.addEventListener("focusout", event => { if (event.target.closest?.("[data-report-tip]")) hide(); }); window.addEventListener("scroll",hide,{passive:true}); window.addEventListener("resize",hide);
    }

