    function renderCommandPalette(filter = "") {
        const list = premiumNode("reportCommandList"); if (!list) return; const term = clean(filter).toLowerCase(); premiumUi.commandItems = premiumCommands().filter(item => !term || `${item.label} ${item.hint}`.toLowerCase().includes(term)); premiumUi.commandIndex = Math.min(premiumUi.commandIndex,premiumUi.commandItems.length-1); if (premiumUi.commandIndex < 0) premiumUi.commandIndex = 0;
        list.innerHTML = premiumUi.commandItems.length ? premiumUi.commandItems.map((item,index) => `<button type="button" class="report-command-item ${index===premiumUi.commandIndex ? "active" : ""}" data-command-index="${index}"><i class="fa-solid ${item.icon}"></i><div><strong>${esc(item.label)}</strong><span>${esc(item.hint)}</span></div>${item.key ? `<kbd>${esc(item.key)}</kbd>` : ""}</button>`).join("") : `<div class="report-command-empty"><i class="fa-solid fa-magnifying-glass"></i><br>No report command matches that search.</div>`;
        $$('[data-command-index]',list).forEach(button => button.addEventListener("click",() => runPremiumCommand(Number(button.dataset.commandIndex))));
    }

    function openCommandPalette() { const palette = premiumNode("reportCommandPalette"), input = premiumNode("reportCommandInput"); if (!palette) return; premiumUi.commandIndex=0; palette.classList.add("open"); palette.setAttribute("aria-hidden","false"); if (input) { input.value=""; setTimeout(() => input.focus(),20); } renderCommandPalette(); }
    function closeCommandPalette() { const palette = premiumNode("reportCommandPalette"); if (!palette) return; palette.classList.remove("open"); palette.setAttribute("aria-hidden","true"); }
    function runPremiumCommand(index) { const item = premiumUi.commandItems[index]; if (!item) return; closeCommandPalette(); item.action(); }

    function initCommandPalette() {
        const button = premiumNode("reportCommandBtn"), close = premiumNode("reportCommandClose"), input = premiumNode("reportCommandInput"), palette = premiumNode("reportCommandPalette"); button?.addEventListener("click",openCommandPalette); close?.addEventListener("click",closeCommandPalette); input?.addEventListener("input",() => { premiumUi.commandIndex=0; renderCommandPalette(input.value); }); palette?.addEventListener("click",event => { if (event.target===palette) closeCommandPalette(); });
        document.addEventListener("keydown",event => { const combo = (event.ctrlKey||event.metaKey) && event.key.toLowerCase()==="k"; if (combo) { event.preventDefault(); return palette?.classList.contains("open") ? closeCommandPalette() : openCommandPalette(); } if (event.key==="Escape" && palette?.classList.contains("open")) { event.preventDefault(); return closeCommandPalette(); } if (!palette?.classList.contains("open")) { if (event.altKey && event.key.toLowerCase()==="l") { event.preventDefault(); return els.loadStudents?.click(); } if (event.altKey && event.key.toLowerCase()==="g") { event.preventDefault(); return els.generateAll?.click(); } return; } if (event.key==="ArrowDown") { event.preventDefault(); premiumUi.commandIndex=Math.min(premiumUi.commandIndex+1,Math.max(0,premiumUi.commandItems.length-1)); renderCommandPalette(input?.value||""); } if (event.key==="ArrowUp") { event.preventDefault(); premiumUi.commandIndex=Math.max(0,premiumUi.commandIndex-1); renderCommandPalette(input?.value||""); } if (event.key==="Enter") { event.preventDefault(); runPremiumCommand(premiumUi.commandIndex); } });
    }

    function initAppDock() {
        const items = $$('[data-report-jump]'); items.forEach(item => item.addEventListener("click",() => premiumScroll(item.dataset.reportJump)));
        if (!("IntersectionObserver" in window)) return; const targets = items.map(item => document.querySelector(item.dataset.reportJump)).filter(Boolean); const observer = new IntersectionObserver(entries => { const visible = entries.filter(entry => entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0]; if (!visible) return; items.forEach(item => item.classList.toggle("active",document.querySelector(item.dataset.reportJump)===visible.target)); },{ rootMargin:"-28% 0px -62% 0px",threshold:[0,.08,.3] }); targets.forEach(target=>observer.observe(target));
    }

    function initSetupProgressListeners() { [els.session,els.term,els.level,els.arm,els.formTeacher,els.nextTerm].filter(Boolean).forEach(node => { node.addEventListener("change",updateSetupProgress); node.addEventListener("input",updateSetupProgress); }); updateSetupProgress(); syncNextTermLoadGate(); }

